+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    @Test
+    void the_form_is_there_and_send_is_enabled() {
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertThat(page.getByRole(com.microsoft.playwright.options.AriaRole.LINK,
+                new com.microsoft.playwright.Page.GetByRoleOptions().setName("About"))).isVisible();
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", message().getValue());
+        assertTrue(send().isEnabled());
+    }
+
+    @Test
+    void empty_form_shows_the_errors() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void invalid_email_shows_its_error_and_keeps_the_input() {
+        name().setValue("Ada");
+        email().setValue("not-an-email");
+        message().setValue("Hi");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValue("Ada");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void too_long_message_shows_its_error() {
+        name().setValue("Ada");
+        phone().setValue("123456");
+        message().setValue("x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+    }
+
+    @Test
+    void sending_shows_a_notification_and_clears_the_form() {
+        name().setValue("Ada");
+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(1, grid.getTotalRowCount());
+        assertThat(grid.findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Ada");
+        assertThat(grid.findCell(0, 1).orElseThrow().getCellContentLocator())
+                .hasText("Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertDisabled();
+
+        name().setValue("B");
+        send().assertEnabled();
+    }
+
+    @Test
+    void enter_sends_the_form() {
+        name().setValue("Ada");
+        phone().setValue("123456");
+        message().setValue("Hello");
+        message().getInputLocator().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void messages_survive_leaving_the_view() {
+        name().setValue("Ada");
+        phone().setValue("123456");
+        message().setValue("First");
+        send().click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true))
+                .click();
+        assertThat(page.locator("h1")).hasText("About");
+
+        page.getByText("Contact",
+                new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void empty_form_leaves_without_asking() {
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true))
+                .click();
+
+        assertThat(page.locator("h1")).hasText("About");
+        assertFalse(page.getByText("Keep editing").isVisible(), "No dialog for an empty form");
+    }
+
+    @Test
+    void keep_editing_stays_and_discard_leaves() {
+        name().setValue("Ada");
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true))
+                .click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+        assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+
+        page.getByText("About", new com.microsoft.playwright.Page.GetByTextOptions().setExact(true))
+                .click();
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+        assertThat(page.locator("h1")).hasText("About");
+    }
+}
